/* Paginate long data tables so the headers remain close to the visible rows. */
let crmTablePageId=0;
function crmUpdateTablePagination(table){
 if(!table||!table.closest('.tablewrap'))return;
 if(table.classList.contains('hierarchy-table')){[...table.tBodies[0]?.rows||[]].forEach(r=>r.hidden=false);table.dataset.pageSize='all';table.dataset.page='1';table.closest('.tablewrap')?.parentElement?.querySelector('[data-table-pager="'+table.id+'"]')?.remove();return}
 const body=table.tBodies[0];if(!body)return;
 const rows=[...body.rows],wrap=table.closest('.tablewrap');
 if(rows.length<=10){rows.forEach(r=>r.hidden=false);wrap.parentElement?.querySelector('[data-table-pager="'+table.id+'"]')?.remove();return}
 if(!table.id)table.id='crm-data-table-'+(++crmTablePageId);
 const size=table.dataset.pageSize==='all'?rows.length:Math.max(1,Number(table.dataset.pageSize||10)),pages=Math.max(1,Math.ceil(rows.length/size));
 const page=Math.min(Math.max(1,Number(table.dataset.page||1)),pages);table.dataset.page=String(page);
 rows.forEach((r,i)=>r.hidden=i<(page-1)*size||i>=page*size);
 let bar=wrap.parentElement?.querySelector('[data-table-pager="'+table.id+'"]');
 if(!bar){bar=document.createElement('div');bar.className='table-pagination';bar.dataset.tablePager=table.id;bar.innerHTML='<button type="button" class="btn small" data-crm-page="-1">ก่อนหน้า</button><span class="pager-status"></span><label>แสดง <select data-crm-size><option value="10">10</option><option value="25">25</option><option value="50">50</option><option value="all">ทั้งหมด</option></select> แถว</label><button type="button" class="btn small" data-crm-page="1">ถัดไป</button>';wrap.parentElement.insertBefore(bar,wrap)}
 const status=bar.querySelector('.pager-status'),statusText=page+'/'+pages+' · '+((page-1)*size+1)+'–'+Math.min(page*size,rows.length)+' จาก '+rows.length+' รายการ';if(status&&status.textContent!==statusText)status.textContent=statusText;
 const select=bar.querySelector('[data-crm-size]');if(select)select.value=table.dataset.pageSize||'10';
 const buttons=bar.querySelectorAll('[data-crm-page]');if(buttons.length===2){buttons[0].disabled=page<=1;buttons[1].disabled=page>=pages}
}
function crmScanTablePagination(){document.querySelectorAll('.tablewrap table').forEach(crmUpdateTablePagination)}
document.addEventListener('click',function(e){const b=e.target.closest('[data-crm-page]');if(!b)return;const bar=b.closest('[data-table-pager]'),table=bar&&document.getElementById(bar.dataset.tablePager);if(!table)return;table.dataset.page=String(Math.max(1,Number(table.dataset.page||1)+Number(b.dataset.crmPage)));crmUpdateTablePagination(table)});
