function buildFollowupRecords(sale,type,part,sub,entries,batch=id('BATCH')){if(!sale||!type||!part||!sub)throw Error('เลือกพนักงาน Product Type, PART และ SUB-PART ให้ครบ');if(!entries.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');return entries.map(e=>{const isProspect=e.Customer_Type==='PROSPECT',customer=isProspect?null:rows('customers').find(c=>c.Customer_Code===e.Customer_Code),prospect=isProspect?(rows('prospects').find(p=>p.Prospect_ID===e.Prospect_ID)||{}):null,qty=Number(e.Plan_Qty),kg=Number(e.KG_Per_UOM),due=normDate(e.Due_Date),prospectName=prospect?.Prospect_Name||String(e.Prospect_Name||'').trim();if(!(qty>0)||!due||!e.Action_Type||!e.Plan_UOM||!(kg>0)||(!isProspect&&!customer)||(isProspect&&!prospectName))throw Error('กรอกรายละเอียด Plan ให้ครบทุกแถว และเลือกหรือเพิ่ม Prospect');return {Action_ID:id('ACT'),Created_Date:localToday(),Due_Date:due,Sale_ID:sale.Sale_ID,Customer_Code:customer?.Customer_Code||'',Item_Code:'',Action_Type:e.Action_Type,Expected_Qty_MT:qty*kg/1000,Status:'OPEN',Result:e.Action_Detail||'',Next_Action:'',Data_Status:'LIVE',Channel:sale.Channel||sale.Team||'',Plan_MT:qty*kg/1000,Closed_Sales_MT:0,Parent_Action_ID:'',Is_Deleted:'N',Manager_Comment:'',Updated_By:me,Updated_At:new Date().toISOString(),Plan_Qty:qty,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg,Plan_KG:qty*kg,Closed_Sales_Qty:0,Closed_Sales_UOM:e.Plan_UOM,Prospect_ID:isProspect?(prospect?.Prospect_ID||e.Prospect_ID||''):'',Prospect_Name:isProspect?prospectName:'',Batch_ID:batch,Product_Type:type,PART:part,SUB_PART:sub,Next_Action_Date:''}})}
async function saveActionBatch(){try{const sale=rows('sales').find(s=>s.Sale_ID===$('#baSale').value),type=$('#baType').value,part=$('#baPart').value,sub=$('#baSub').value,els=[...document.querySelectorAll('[data-action-plan]')],batch=id('BATCH'),entries=els.map(el=>{const u=el.querySelector('[data-a-uom]').selectedOptions[0],isProspect=el.querySelector('[data-a-customer-type]').value==='PROSPECT',chosen=el.querySelector('[data-a-prospect-select]')?.value||'';return {Due_Date:el.querySelector('[data-a-date]').value,Action_Type:el.querySelector('[data-a-kind]').value,Customer_Type:isProspect?'PROSPECT':'OLD',Customer_Code:el.querySelector('[data-a-customer]').value,Prospect_ID:chosen&&chosen!=='__NEW__'?chosen:'',Prospect_Name:chosen==='__NEW__'?el.querySelector('[data-a-prospect]').value:'',Plan_Qty:el.querySelector('[data-a-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg,Action_Detail:el.querySelector('[data-a-detail]').value}}),prospectAdds=[],newByName=new Map();for(const e of entries.filter(x=>x.Customer_Type==='PROSPECT')){let p=e.Prospect_ID?rows('prospects').find(x=>x.Prospect_ID===e.Prospect_ID):null;const name=String(e.Prospect_Name||'').trim(),key=name.toLocaleLowerCase();if(!p&&key)p=rows('prospects').find(x=>String(x.Prospect_Name||'').trim().toLocaleLowerCase()===key&&(!x.Channel||x.Channel===(sale?.Channel||sale?.Team||''))&&String(x.Data_Status||'LIVE').toUpperCase()!=='DELETED');if(!p&&key)p=newByName.get(key);if(!p){if(!key)throw Error('เลือก Prospect เดิม หรือระบุชื่อ Prospect ใหม่ในทุกรายการ');p={Prospect_ID:id('PRO'),Prospect_Name:name,Channel:sale?.Channel||sale?.Team||'',Owner_Sale_ID:sale?.Sale_ID||'',Product_Type:type,PART:part,SUB_PART:sub,Status:'ACTIVE',Created_By:me,Created_At:new Date().toISOString(),Data_Status:'LIVE',Product_Interest:[type,part,sub].join(' / ')};newByName.set(key,p);prospectAdds.push(p)}e.Prospect_ID=p.Prospect_ID;e.Prospect_Name=p.Prospect_Name}const objects=buildFollowupRecords(sale,type,part,sub,entries,batch);if(prospectAdds.length)await append(TAB.prospects,prospectAdds);await append(TAB.actions,objects);await append(TAB.actionHistory,objects.map(o=>({History_ID:id('HIS'),Action_ID:o.Action_ID,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'CREATE',New_Status:o.Status,New_Due_Date:o.Due_Date,New_Plan_MT:o.Plan_MT,New_Next_Action:o.Next_Action})));closeModal();ping(`บันทึก Action ${objects.length} รายการ · Prospect ใหม่ ${prospectAdds.length} ราย`);await loadDb()}catch(e){ping(e.message,true)}}
