function productOptions(groups,field,value){const vals=[...new Set(groups.map(g=>String(g[field]||'')).filter(Boolean))];return `<option value="">เลือก ${field==='Group_Product_ID'?'GROUP PRODUCT':field}</option>${vals.map(v=>{const g=groups.find(x=>String(x[field])===v),label=field==='Group_Product_ID'?(g.Group_Product_Name||v):v;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`}).join('')}`}
