function setBatchUoms(el){el.querySelector('[data-a-customer]').innerHTML='<option value="">เลือกลูกค้า</option>'+customerLovOptionsForGroup();el.querySelector('[data-a-prospect-select]').innerHTML='<option value="">เลือก Prospect</option>'+prospectLovOptions('','','')+'<option value="__NEW__">+ เพิ่ม Prospect ใหม่</option>'}
function addActionPlanRow(){const box=$('#actionPlanRows'),n=box.querySelectorAll('[data-action-plan]').length;box.insertAdjacentHTML('beforeend',batchPlanRow(n));const el=box.lastElementChild;setBatchUoms(el);el.querySelector('[data-a-customer-type]').onchange=e=>{const p=e.target.value==='PROSPECT';el.querySelector('[data-a-customer-box]').classList.toggle('hidden',p);el.querySelector('[data-a-prospect-select-box]').classList.toggle('hidden',!p);if(!p)el.querySelector('[data-a-prospect-box]').classList.add('hidden')};el.querySelector('[data-a-prospect-select]').onchange=e=>el.querySelector('[data-a-prospect-box]').classList.toggle('hidden',e.target.value!=='__NEW__');el.querySelector('[data-add-product]').onclick=()=>addPlanProduct(el);el.querySelector('[data-remove-plan]').onclick=()=>el.remove();addPlanProduct(el)}
function buildFollowupRecords(sale,entries,batch=id('BATCH')){if(!sale||!entries.length)throw Error('กรอกพนักงานและรายละเอียด Plan');return entries.map(e=>{const isP=e.Customer_Type==='PROSPECT',c=isP?null:rows('customers').find(x=>x.Customer_Code===e.Customer_Code),p=isP?rows('prospects').find(x=>x.Prospect_ID===e.Prospect_ID):null,q=Number(e.Plan_Qty),kg=Number(e.KG_Per_UOM),due=normDate(e.Due_Date),name=p?.Prospect_Name||String(e.Prospect_Name||'').trim();if(!(q>0)||!due||!e.Action_Type||!e.Plan_UOM||!(kg>0)||(!isP&&!c)||(isP&&!name))throw Error('กรอกวันที่ ลูกค้า/Prospect และจำนวนสินค้าใน Plan ให้ครบ');if(!e.Product_Type||!e.Action_Product_Level)throw Error('เลือก Product Type, PART, SUB-PART หรือ Group Product อย่างน้อยหนึ่งรายการ');return {Action_ID:id('ACT'),Created_Date:localToday(),Due_Date:due,Sale_ID:sale.Sale_ID,Customer_Code:c?.Customer_Code||'',Item_Code:'',Action_Type:e.Action_Type,Expected_Qty_MT:q*kg/1000,Status:'OPEN',Result:e.Action_Detail||'',Next_Action:'',Data_Status:'LIVE',Channel:sale.Channel||sale.Team||'',Plan_MT:q*kg/1000,Closed_Sales_MT:0,Parent_Action_ID:'',Is_Deleted:'N',Manager_Comment:'',Updated_By:me,Updated_At:new Date().toISOString(),Plan_Qty:q,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg,Plan_KG:q*kg,Closed_Sales_Qty:0,Closed_Sales_UOM:e.Plan_UOM,Prospect_ID:isP?(p?.Prospect_ID||e.Prospect_ID||''):'',Prospect_Name:isP?name:'',Batch_ID:batch,Product_Type:e.Product_Type,PART:e.PART,SUB_PART:e.SUB_PART,Next_Action_Date:'',Plan_Group_ID:e.Plan_Group_ID,Action_Product_Level:e.Action_Product_Level,Group_Product_ID:e.Group_Product_ID||'',Group_Product_Name:e.Group_Product_Name||''}})}
async function saveActionBatch(){try{const sale=rows('sales').find(s=>s.Sale_ID===$('#baSale').value),parents=[...document.querySelectorAll('[data-action-plan]')],batch=id('BATCH'),entries=[],prospectAdds=[],byName=new Map();for(const parent of parents){const isP=parent.querySelector('[data-a-customer-type]').value==='PROSPECT',chosen=parent.querySelector('[data-a-prospect-select]')?.value||'',base={Due_Date:parent.querySelector('[data-a-date]').value,Action_Type:parent.querySelector('[data-a-kind]').value,Customer_Type:isP?'PROSPECT':'OLD',Customer_Code:parent.querySelector('[data-a-customer]').value,Prospect_ID:chosen&&chosen!=='__NEW__'?chosen:'',Prospect_Name:chosen==='__NEW__'?parent.querySelector('[data-a-prospect]').value.trim():'',Action_Detail:parent.querySelector('[data-a-detail]').value,Plan_Group_ID:id('PLAN')},lines=[...parent.querySelectorAll('[data-plan-product]')];if(!lines.length)throw Error('เพิ่มสินค้าอย่างน้อย 1 รายการในแต่ละ Plan');for(const el of lines){const get=k=>el.querySelector(`[data-prod-field="${k}"]`)?.value||'',u=el.querySelector('[data-prod-uom]')?.selectedOptions[0],g=productMasterOptions().find(x=>String(x.Group_Product_ID||'')===get('Group_Product_ID'));entries.push({...base,Product_Type:get('Product_Type'),PART:get('PART'),SUB_PART:get('SUB_PART'),Group_Product_ID:get('Group_Product_ID'),Group_Product_Name:g?.Group_Product_Name||'',Action_Product_Level:(el.dataset.planLevel||'Product_Type')==='Group_Product_ID'?'GROUP_PRODUCT':el.dataset.planLevel||'Product_Type',Plan_Qty:el.querySelector('[data-prod-qty]').value,Plan_UOM:u?.value,KG_Per_UOM:u?.dataset.kg})}}for(const e of entries.filter(x=>x.Customer_Type==='PROSPECT')){let p=e.Prospect_ID?rows('prospects').find(x=>x.Prospect_ID===e.Prospect_ID):null;const name=String(e.Prospect_Name||'').trim(),key=name.toLocaleLowerCase();if(!p&&key)p=rows('prospects').find(x=>String(x.Prospect_Name||'').trim().toLocaleLowerCase()===key&&(!x.Channel||x.Channel===(sale?.Channel||sale?.Team||''))&&String(x.Data_Status||'LIVE').toUpperCase()!=='DELETED');if(!p&&key)p=byName.get(key);if(!p){if(!key)throw Error('เลือกลูกค้า Prospect เดิม หรือกรอกชื่อ Prospect ใหม่');p={Prospect_ID:id('PRO'),Prospect_Name:name,Channel:sale?.Channel||sale?.Team||'',Owner_Sale_ID:sale?.Sale_ID||'',Product_Type:e.Product_Type,PART:e.PART,SUB_PART:e.SUB_PART,Status:'ACTIVE',Created_By:me,Created_At:new Date().toISOString(),Data_Status:'LIVE',Product_Interest:[e.Product_Type,e.PART,e.SUB_PART].filter(Boolean).join(' / ')};byName.set(key,p);prospectAdds.push(p)}e.Prospect_ID=p.Prospect_ID;e.Prospect_Name=p.Prospect_Name}const objects=buildFollowupRecords(sale,entries,batch);if(prospectAdds.length)await append(TAB.prospects,prospectAdds);await append(TAB.actions,objects);await append(TAB.actionHistory,objects.map(o=>({History_ID:id('HIS'),Action_ID:o.Action_ID,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'CREATE',New_Status:o.Status,New_Due_Date:o.Due_Date,New_Plan_MT:o.Plan_MT,New_Next_Action:o.Next_Action})));closeModal();ping(`บันทึก ${parents.length} Plan · ${objects.length} รายการสินค้า · Prospect ใหม่ ${prospectAdds.length} ราย`);await loadDb()}catch(e){ping(e.message,true)}}
function actionCustomerName(a){return rows('customers').find(c=>c.Customer_Code===a.Customer_Code)?.Customer_Name||rows('prospects').find(p=>p.Prospect_ID===a.Prospect_ID)?.Prospect_Name||a.Prospect_Name||a.Customer_Code||'—'}

function masterFieldInput(key,existing={}){
 if(mtab==='prospects'&&key==='Created_By')return '<input data-master-key="Created_By" readonly value="'+esc(existing.Created_By||me||'')+'" title="ระบบใช้บัญชีที่เชื่อมต่อเป็นผู้สร้าง">';
 if(mtab==='prospects'&&key==='Created_At')return '<input data-master-key="Created_At" readonly value="'+esc(existing.Created_At||new Date().toISOString())+'" title="ระบบบันทึกวันและเวลาให้อัตโนมัติ">';
 if(mtab==='customers'&&['Customer_Segment','Route','Customer_Status','Assigned_Sale_ID','Channel','Customer_Group','Update_Status','Sales_Route'].includes(key)){
  const lookupKey=key==='Customer_Group'?'Customer_Segment':key==='Update_Status'?'Customer_Status':key==='Sales_Route'?'Route':key,current=String(existing[key]??'');
  const values=lookupKey==='Assigned_Sale_ID'?active(rows('sales')).map(x=>[x.Sale_ID,(x.Sale_Name||x.Sale_ID)+' · '+x.Sale_ID]):lookupKey==='Channel'?channelUniqueRows().map(x=>[x.Channel_Code,x.Channel_Name||x.Channel_Code]):customerLookupRows(lookupKey);
  if(current&&!values.some(x=>String(x[0])===current))values.unshift([current,current]);
  return '<select data-master-key="'+esc(key)+'"><option value="">เลือก '+esc(key.replace(/_/g,' '))+'</option>'+values.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(v)===current?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';
 }
 if(mtab==='prospects'&&['Owner_Sale_ID','Channel'].includes(key)){
  const current=String(existing[key]??''),values=key==='Owner_Sale_ID'?active(rows('sales')).map(x=>[x.Sale_ID,x.Sale_Name||x.Sale_ID]):channelUniqueRows().map(x=>[x.Channel_Code,x.Channel_Name||x.Channel_Code]);
  return '<select data-master-key="'+esc(key)+'"><option value="">เลือก '+esc(key)+'</option>'+values.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(v)===current?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';
 }
 if(mtab==='prospects'&&['Product_Type','PART','SUB_PART','Group_Product_ID'].includes(key)){
  const groups=productMasterOptions(),current=String(existing[key]??''),values=[...new Set(groups.map(g=>String(g[key]||'')).filter(Boolean))];
  return '<select data-master-key="'+esc(key)+'"><option value="">เลือก '+esc(key)+'</option>'+values.map(v=>{const g=groups.find(x=>String(x[key])===v),label=key==='Group_Product_ID'?(g.Group_Product_Name||v):v;return '<option value="'+esc(v)+'" '+(v===current?'selected':'')+'>'+esc(label)+'</option>'}).join('')+'</select>';
 }
 if(mtab==='customers'&&key==='Product_Interest'){
  const current=String(existing[key]??''),opts=active(rows('groupProducts')).map(g=>[g.Group_Product_ID,g.Group_Product_Name||g.Group_Product_ID]);
  return '<select data-master-key="Product_Interest"><option value="">เลือก Group Product ที่สนใจ</option>'+opts.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(v)===current?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';
 }
 if(mtab==='channels'&&key==='Channel_Code')return '<input data-master-key="Channel_Code" value="'+esc(existing[key]||'')+'" placeholder="รหัส Channel">';
 return masterFieldInputBase(key,existing);
}
function syncProspectMasterHierarchy(changedKey,changedValue){
 const keys=['Product_Type','PART','SUB_PART','Group_Product_ID'],all=productMasterOptions(),old=Object.fromEntries(keys.map(k=>[k,document.querySelector('[data-master-key="'+k+'"]')?.value||'']));
 old[changedKey]=changedValue;let pool=all.filter(g=>keys.every(k=>!old[k]||String(g[k]||'')===old[k]));
 if(!pool.length){for(const k of keys)if(k!==changedKey)old[k]='';pool=all.filter(g=>!old[changedKey]||String(g[changedKey]||'')===old[changedKey])}
 for(const k of keys){const sel=document.querySelector('[data-master-key="'+k+'"]');if(!sel)continue;const vals=[...new Set(pool.map(g=>String(g[k]||'')).filter(Boolean))],v=old[k]&&vals.includes(old[k])?old[k]:vals.length===1?vals[0]:'';sel.innerHTML='<option value="">เลือก '+esc(k)+'</option>'+vals.map(x=>{const g=pool.find(y=>String(y[k])===x),label=k==='Group_Product_ID'?(g.Group_Product_Name||x):x;return '<option value="'+esc(x)+'">'+esc(label)+'</option>'}).join('');sel.value=v}
}
if(!window.crmProspectHierarchyBound){document.addEventListener('change',e=>{if(mtab==='prospects'&&e.target?.matches('[data-master-key="Product_Type"],[data-master-key="PART"],[data-master-key="SUB_PART"],[data-master-key="Group_Product_ID"]'))syncProspectMasterHierarchy(e.target.dataset.masterKey,e.target.value)});window.crmProspectHierarchyBound=true}
